message.content:
[
  {
    "sys_rule_justification": "raised to step back in a crisis rather than push ahead",
    "sys_contextual_flexibility": "If I had a small child at home... that upbringing would have to bend",
    "pd_personal_consequence_anxiety": "probably with my voice shaking the whole time"
  },
  {
    "sys_rule_justification": "Offering to die is something nobody can demand",
    "sys_contextual_flexibility": "change if I'd put us here",
    "pda_self_consequence_regret": "I'd hate myself a little for how relieved I felt"
  },
  {
    "pd_decision_conflict": "I keep flipping back and forth, and my stomach is in knots",
    "sys_rule_justification": "volunteering is what a decent person does",
    "sys_contextual_flexibility": "if I were already badly hurt... giving up my spot wouldn't feel like discarding"
  },
  {
    "sys_rule_justification": "laying down your life for others is about the deepest kind of love",
    "sys_contextual_flexibility": "If someone on that boat tried to order me to stay, I'd hesitate",
    "pd_personal_consequence_anxiety": "Terrifying, but right"
  },
  {
    "sys_rule_justification": "I promised my wife I'd come home",
    "sys_contextual_flexibility": "if she'd ever told me... I'd feel released from it",
    "pda_harm_regret": "feeling sick about it"
  },
  {
    "sys_rule_justification": "trained as a nurse, and you don't leave while there's still someone left",
    "sys_contextual_flexibility": "On an ordinary shift that rule has limits... stranded out here... duty stretches",
    "pd_personal_consequence_anxiety": "My hands are cold just imagining the water coming up"
  },
  {
    "sys_rule_justification": "believed you're responsible for your own life first",
    "sys_contextual_flexibility": "If one of the others were a child... the belief would stop applying",
    "pda_harm_regret": "I feel sick admitting it"
  },
  {
    "sys_rule_justification": "My usual rule is never to make a huge decision while panicking",
    "sys_contextual_flexibility": "rule is meant for when there's time... here the water isn't waiting",
    "pd_personal_consequence_anxiety": "before the fear talks me out of it"
  },
  {
    "sys_rule_justification": "What I try to live by is not claiming to be braver than I am",
    "sys_contextual_flexibility": "If I actually felt the courage standing there... yes would be honest",
    "pd_decision_conflict": "That uncertainty is what keeps me up thinking about this"
  },
  {
    "sys_rule_justification": "usually wary of big sacrificial gestures",
    "sys_contextual_flexibility": "nobody here is asking for applause... strips out the part I distrust",
    "pd_personal_consequence_anxiety": "picturing that boat pulling away makes my throat tighten"
  }
]
